<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {ShieldCheck,X} from 'lucide-vue-next'
import type {ToolApprovalDraft} from '../tool-approvals'
import {sandboxBudget} from '../tool-approvals'
import {networkLabel,resourceLabel} from '../capability-ui'
const props=defineProps<{draft:ToolApprovalDraft|null;sessionName:string;publicQuery?:string}>()
const emit=defineEmits<{confirm:[];cancel:[];publicQuery:[value:string]}>()
const needsPublicQuery=computed(()=>props.draft?.tools.some(tool=>tool.network_policy==='public-https'))
const validPublicQuery=computed(()=>!needsPublicQuery.value||typeof props.publicQuery==='string'&&!!props.publicQuery.trim()&&props.publicQuery.trim().length<=400)
const dialog=ref<HTMLDialogElement>(),cancelButton=ref<HTMLButtonElement>()
let opener:HTMLElement|null=null
watch(()=>props.draft,async value=>{if(value){opener=document.activeElement as HTMLElement;dialog.value?.showModal();await nextTick();cancelButton.value?.focus()}else{dialog.value?.close();if(opener?.isConnected)opener.focus()}})
onBeforeUnmount(()=>dialog.value?.close())
</script>
<template><dialog ref="dialog" class="approval-dialog" aria-labelledby="tool-approval-title" aria-describedby="tool-approval-description" @cancel.prevent="emit('cancel')"><template v-if="draft"><header><ShieldCheck :size="24"/><div><small>仅本次任务 · 目录修订 {{draft.revision}}</small><h2 id="tool-approval-title">确认工具授权</h2></div><button class="icon" aria-label="取消工具授权" @click="emit('cancel')"><X/></button></header><section class="approval-body" tabindex="0" aria-label="工具授权范围与限额"><p id="tool-approval-description">能力 <strong>/{{draft.skillName}}</strong> 需要使用以下工具。确认后仅授权当前账号在这次任务中使用，后续任务需要重新确认。</p><p class="binding">当前对话：{{sessionName||'发送时创建的新对话'}}</p><label v-if="needsPublicQuery" class="public-query">本轮允许发送给公共工具的查询<textarea :value="publicQuery" @input="emit('publicQuery',($event.target as HTMLTextAreaElement).value)" maxlength="400" rows="3" autocomplete="off"/><small>仅此查询会发送到公共网络。可移除私有内容；查询须为 1–400 字。</small></label><ul><li v-for="tool in draft.tools" :key="tool.name"><code>{{tool.name}} · v{{tool.version}}</code><p>{{tool.description}}</p><small>{{networkLabel(tool.network_policy)}} · {{resourceLabel(tool.resource_scope)}}</small><dl v-if="tool.resource_scope==='isolated-workspace'" class="budgets" aria-label="本次隔离执行资源限额"><div v-for="[label,value] in sandboxBudget(tool)" :key="label"><dt>{{label}}</dt><dd>{{value}}</dd></div></dl><p v-if="!tool.idempotent" class="policy">此工具可能产生副作用，结果未确认时不会自动重复执行。</p></li></ul><p class="policy">授权不扩大资料权限、公开输入、网络和执行预算。取消会保留草稿。</p></section><footer><button ref="cancelButton" class="secondary" @click="emit('cancel')">取消，保留草稿</button><button class="primary" :disabled="!validPublicQuery" @click="validPublicQuery&&emit('confirm')">确认并发送</button></footer></template></dialog></template>
<style scoped>
.approval-dialog{width:min(620px,94vw);max-height:86vh;overflow:auto;padding:28px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink)}.approval-dialog[open]{display:flex;flex-direction:column;overflow:hidden}.approval-body{overflow:auto;min-height:0;flex:1;padding-right:6px}.approval-dialog header,.approval-dialog footer{flex-shrink:0}.approval-dialog::backdrop{background:#102c2270;backdrop-filter:blur(3px)}header{display:flex;align-items:center;gap:14px;color:var(--green)}header>div{flex:1}header small{font-size:10px;letter-spacing:.05em}h2{font:24px 'Noto Serif SC',serif;margin:7px 0}p{font-size:13px;line-height:1.9}.binding,.policy{color:var(--muted);font-size:12px}ul{list-style:none;padding:0;margin:24px 0;border-block:1px solid var(--line)}li{padding:18px 0;border-bottom:1px solid var(--line)}li:last-child{border:0}li p{margin:8px 0}li code{color:var(--green);font-size:12px;overflow-wrap:anywhere}li small{font-size:11px;color:var(--muted)}footer{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}@media(max-width:520px){.approval-dialog{padding:22px}footer{flex-direction:column-reverse}}
.budgets{display:grid;grid-template-columns:1fr 1fr;gap:10px 18px;margin:16px 0;padding:14px;background:var(--paper,var(--surface));border:1px solid var(--line);border-radius:8px}.budgets div:last-child{grid-column:1/-1}.budgets dt{font-size:11px;color:var(--muted)}.budgets dd{margin:4px 0 0;font-size:12px;line-height:1.6}@media(max-width:380px){.budgets{grid-template-columns:1fr}}
.public-query{display:flex;flex-direction:column;gap:8px;font-size:12px;color:var(--green)}.public-query textarea{width:100%;resize:vertical;min-height:70px;padding:10px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:var(--ink);font:inherit}.public-query small{color:var(--muted);line-height:1.7}
</style>
